import { Suspense, lazy, useEffect, useState, type ReactNode } from 'react';
import type { Meta, StoryObj } from '@storybook/react-native-web-vite';
import { View } from 'react-native';

import { isFigmaComponentCaptureMode } from '../storybookCaptureMode';
import { activePaintRenderer, isMultiPaintProfile } from '../catalogPaintProfile';
import { CatalogPaintBrowsePreview } from '../CatalogPaintRendererStrip';
import { componentStoryMetadataForSpec } from '../figmaComponentStoryMetadataFactory';
import type { FigmaComponentStorySpec } from '../figmaComponentStorySpec';
import type {
  StoryFixtureCapability,
  StoryFixtureCapabilityId,
} from '../storyFixtureCapability';
import {
  loadPinnedComponentFrameGeometry,
  resolveAdaptiveComponentFrameTranslation,
} from '../rawComponentFrameGeometry';

const ComponentComparisonReviewHost = lazy(() => import('../componentComparisonReviewHost'));

const FIGMA_CATALOG_META_ID = 'components-figma-catalog';
const STORY_FIXTURE_CAPABILITY_REGISTRY_KEY = Symbol.for(
  'onyx.story-fixture-capability-owner-registry',
);

function registeredStoryFixtureCapabilityOwner(
  id: StoryFixtureCapabilityId,
): StoryFixtureCapability | undefined {
  const registryGlobal = globalThis as typeof globalThis & Record<symbol, unknown>;
  const registry = registryGlobal[STORY_FIXTURE_CAPABILITY_REGISTRY_KEY] as
    | Map<StoryFixtureCapabilityId, StoryFixtureCapability>
    | undefined;
  return registry?.get(id);
}

export type FigmaCatalogStory = StoryObj & {
  args?: Record<string, any>;
  argTypes?: Record<string, any>;
  render?: (args: Record<string, any>) => ReactNode;
};

type CatalogPaintProfile = {
  tileSize?: number;
  tileGap?: number;
  frame: { width: number; height: number; background?: string };
  renderers: Parameters<typeof CatalogPaintBrowsePreview>[0]['renderers'];
};

function RawComponentFrame({
  children,
  id,
  width,
  height,
  background = '#18191a',
}: {
  children: ReactNode;
  id: string;
  width: number;
  height: number;
  background?: string;
}) {
  const [translation, setTranslation] = useState({ x: 0, y: 0 });
  const [ownerSize, setOwnerSize] = useState({ width, height });

  useEffect(() => {
    let active = true;
    void loadPinnedComponentFrameGeometry(id)
      .then((geometry) => {
        if (!geometry || !active) return;
        // Fluid catalog children need a definite containing block. The
        // committed owner bounds are distinct from the decorative export canvas.
        setOwnerSize({ width: geometry.exportedRoot.width, height: geometry.exportedRoot.height });
        setTranslation(resolveAdaptiveComponentFrameTranslation({
          canvas: { width, height },
          ...geometry,
        }));
      })
      .catch(() => {
        // Catalog browsing remains usable if a local diagnostic artifact is unavailable.
      });
    return () => { active = false; };
  }, [height, id, width]);

  return (
    <View style={{ alignItems: 'flex-start', backgroundColor: background, height, justifyContent: 'flex-start', overflow: 'visible', width }}>
      <View style={{ ...ownerSize, transform: [{ translateX: translation.x }, { translateY: translation.y }], overflow: 'visible' }}>
        {children}
      </View>
    </View>
  );
}

function FigmaCatalogStoryLayout({
  children,
  height,
  id,
  width,
  background,
  paintProfile,
  spec,
}: {
  children: ReactNode;
  height: number;
  id: string;
  width: number;
  background?: string;
  paintProfile?: CatalogPaintProfile;
  spec: FigmaComponentStorySpec;
}) {
  const captureChild = paintProfile ? activePaintRenderer(paintProfile.renderers).mount : children;
  if (isFigmaComponentCaptureMode()) {
    return (
      <RawComponentFrame id={id} width={width} height={height} background={background}>
        {captureChild}
      </RawComponentFrame>
    );
  }

  const component = componentStoryMetadataForSpec(spec).onyxComponent;
  const multi = paintProfile != null && isMultiPaintProfile(paintProfile);
  const preview = multi && paintProfile ? (
    <CatalogPaintBrowsePreview
      renderers={paintProfile.renderers}
      tileSize={paintProfile.tileSize}
      tileGap={paintProfile.tileGap}
      background={paintProfile.frame.background ?? background}
    />
  ) : (
    <RawComponentFrame id={id} width={width} height={height} background={background}>
      {captureChild}
    </RawComponentFrame>
  );

  return (
    <Suspense fallback={preview}>
      <ComponentComparisonReviewHost component={component} preview={preview} />
    </Suspense>
  );
}

function exportNameToStoryId(exportName: string) {
  return exportName
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1-$2')
    .replace(/([A-Za-z])(\d)/g, '$1-$2')
    .replace(/(\d)([A-Za-z])/g, '$1-$2')
    .toLowerCase();
}

export function figmaCatalogStoryId(exportName: string) {
  return `${FIGMA_CATALOG_META_ID}--${exportNameToStoryId(exportName)}`;
}

function storyNameForSpec(spec: FigmaComponentStorySpec) {
  const variantSuffix = spec.variant ? Object.values(spec.variant).join(' / ') : '';
  return variantSuffix ? `${spec.componentName} / ${variantSuffix}` : spec.componentName;
}

function applyFixtureCapabilities(children: ReactNode, capabilities: readonly StoryFixtureCapability[]) {
  return capabilities.reduceRight((nested, capability) => capability.wrap(nested), children);
}

/** Module-level provider ownership: covers locked stories and Playgrounds. */
export function figmaCatalogStoryDecorators(
  specs: readonly FigmaComponentStorySpec[],
  capabilities: readonly StoryFixtureCapability[],
): NonNullable<Meta['decorators']> {
  const declaredIds = [...new Set(specs.flatMap((spec) => spec.fixtureCapabilities ?? []))];
  const duplicateIds = capabilities
    .map((capability) => capability.id)
    .filter((id, index, ids) => ids.indexOf(id) !== index)
    .filter((id, index, ids) => ids.indexOf(id) === index);
  const capabilityById = new Map(capabilities.map((capability) => [capability.id, capability]));
  const missingIds = declaredIds.filter((id) => !capabilityById.has(id));
  const unexpectedIds = capabilities
    .map((capability) => capability.id)
    .filter((id) => !declaredIds.includes(id));
  const wrongOwnerIds = capabilities
    .filter((capability) => (
      declaredIds.includes(capability.id)
      && registeredStoryFixtureCapabilityOwner(capability.id) !== capability
    ))
    .map((capability) => capability.id)
    .filter((id, index, ids) => ids.indexOf(id) === index);
  if (
    missingIds.length > 0
    || unexpectedIds.length > 0
    || duplicateIds.length > 0
    || wrongOwnerIds.length > 0
  ) {
    throw new Error(
      `Figma catalog fixture capability mismatch (`
        + `missing: ${missingIds.join(', ') || 'none'}; `
        + `unexpected: ${unexpectedIds.join(', ') || 'none'}; `
        + `duplicate: ${duplicateIds.join(', ') || 'none'}; `
        + `wrong-owner: ${wrongOwnerIds.join(', ') || 'none'})`,
    );
  }
  const resolvedCapabilities = declaredIds.map((id) => capabilityById.get(id)!);
  if (resolvedCapabilities.length === 0) return [];
  return [(Story) => <>{applyFixtureCapabilities(<Story />, resolvedCapabilities)}</>];
}

export function createFigmaCatalogStoryFactory(specs: readonly FigmaComponentStorySpec[]) {
  const byId = new Map(specs.map((spec) => [spec.id, spec]));
  const specFor = (id: string) => {
    const spec = byId.get(id);
    if (!spec) throw new Error(`Unknown family-owned Figma catalog story: ${id}`);
    return spec;
  };

  return {
    rawCatalogPaintStory(id: string, profile: CatalogPaintProfile): FigmaCatalogStory {
      const spec = specFor(id);
      const metadata = componentStoryMetadataForSpec(spec);
      const active = activePaintRenderer(profile.renderers);
      return {
        name: storyNameForSpec(spec),
        render: () => (
          <FigmaCatalogStoryLayout
            id={id}
            width={profile.frame.width}
            height={profile.frame.height}
            background={profile.frame.background}
            paintProfile={profile}
            spec={spec}
          >
            {active.mount}
          </FigmaCatalogStoryLayout>
        ),
        parameters: { ...metadata, __id: figmaCatalogStoryId(spec.exportName) },
      };
    },
    rawStory(
      id: string,
      children: ReactNode,
      width: number,
      height: number,
      background?: string,
    ): FigmaCatalogStory {
      const spec = specFor(id);
      const metadata = componentStoryMetadataForSpec(spec);
      return {
        name: storyNameForSpec(spec),
        render: () => (
          <FigmaCatalogStoryLayout
            id={id}
            width={width}
            height={height}
            background={background}
            spec={spec}
          >
            {children}
          </FigmaCatalogStoryLayout>
        ),
        parameters: { ...metadata, __id: figmaCatalogStoryId(spec.exportName) },
      };
    },
  };
}

export function PlaygroundFrame({
  children,
  width = 393,
  height = 220,
}: {
  children: ReactNode;
  width?: number;
  height?: number;
}) {
  return (
    <View style={{ alignItems: 'center', backgroundColor: '#18191a', gap: 16, minHeight: height, justifyContent: 'center', padding: 24, width }}>
      {children}
    </View>
  );
}

